import {Game} from './engine.mjs';
import {camera} from './view.mjs';
const $=id=>document.getElementById(id),g=new Game,canvas=$('arena'),ctx=canvas.getContext('2d'),poster=$('poster'),pc=poster.getContext('2d');
let keys={},joy={x:0,y:0},activePointer=null,last=0,uiState='',sound=false,audio,look=0,shake=0,viewW=1200,viewH=800;
const upgrades=[{id:'damage',icon:'✴',name:'火力全开',desc:'子弹伤害 +8',detail:'每一发，都更有分量'},{id:'rate',icon:'ϟ',name:'快枪土豆',desc:'攻击间隔减少 18%',detail:'手速跟上你的心跳'},{id:'speed',icon:'➜',name:'脚底抹油',desc:'移动速度 +25',detail:'打不过，还跑不过吗'},{id:'health',icon:'♥',name:'厚皮土豆',desc:'生命上限 +20，恢复 40',detail:'皮厚一点，活久一点'},{id:'magnet',icon:'✧',name:'经验磁铁',desc:'拾取范围 +45',detail:'绿的，都是我的'}];
function fit(el,c){let r=el.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(el.width!==Math.round(r.width*d)||el.height!==Math.round(r.height*d)){el.width=Math.round(r.width*d);el.height=Math.round(r.height*d)}c.setTransform(d,0,0,d,0,0);return r}
function oval(c,x,y,rx,ry,fill,stroke='#222b22',line=3){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=line;c.stroke()}}
function path(c,points,fill,stroke='#252d24',width=3){c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fillStyle=fill;c.fill();if(stroke){c.lineWidth=width;c.strokeStyle=stroke;c.lineJoin='round';c.stroke()}}
function potato(c,x,y,s=1,angle=0,t=0,hero=false){c.save();c.translate(x,y);c.scale(s,s);oval(c,0,42,43,10,'#17231d44',null);let bob=Math.sin(t*10)*2;c.translate(0,bob);oval(c,-18,37,12,8,'#9b653e');oval(c,18,37,12,8,'#9b653e');c.save();c.rotate(-.08);c.beginPath();c.moveTo(-34,16);c.bezierCurveTo(-46,-11,-22,-53,8,-48);c.bezierCurveTo(39,-47,45,-11,34,17);c.bezierCurveTo(22,49,-22,48,-34,16);c.fillStyle='#cc9e63';c.fill();c.strokeStyle='#2a2e21';c.lineWidth=3;c.stroke();oval(c,3,-12,27,33,'#e2b67a',null);for(let [a,b] of [[-23,-15],[-18,18],[20,25],[22,-30],[-7,-35]]){oval(c,a,b,2.4,3,'#aa7f4b',null)}c.strokeStyle='#775b3f';c.lineWidth=2;c.beginPath();c.moveTo(-31,-23);c.quadraticCurveTo(-10,-37,32,-17);c.stroke();path(c,[[-34,-22],[-31,-34],[30,-29],[36,-15],[5,-23]],'#aa553e');path(c,[[-30,-29],[-49,-20],[-40,-14],[-34,-17],[-45,-6],[-25,-18]],'#b96947');c.strokeStyle='#2d3023';c.lineWidth=3;c.beginPath();c.moveTo(-14,-7);c.lineTo(-4,-4);c.moveTo(8,-4);c.lineTo(19,-8);c.stroke();oval(c,-8,0,3,5,'#262c21',null);oval(c,14,0,3,5,'#262c21',null);c.beginPath();c.moveTo(-1,15);c.quadraticCurveTo(6,18,13,12);c.stroke();c.restore();c.save();c.rotate(angle);oval(c,29,12,11,9,'#c99b61');path(c,[[21,1],[59,1],[59,14],[40,14],[38,29],[28,27],[30,13],[21,13]],'#4e5850');path(c,[[54,1],[68,1],[68,13],[54,13]],'#859184');path(c,[[28,0],[51,0],[51,5],[28,5]],'#9ba393',null);if(hero){c.fillStyle='#1f2822';c.fillRect(40,6,6,3)}c.restore();oval(c,-30,17,10,9,'#c99b61');c.restore()}
function monster(c,x,y,s=1,type=0,hit=false,t=0){c.save();c.translate(x,y);c.scale(s,s);oval(c,0,16,21,6,'#1b291d33',null);c.translate(0,Math.sin(t*7+x)*2);if(type){path(c,[[-25,13],[-27,-7],[-16,-27],[0,-32],[20,-24],[29,-6],[22,17],[0,23]],hit?'#fff2c9':'#a08fba');path(c,[[-17,-21],[-22,-37],[-5,-28]],'#bbb1c8');path(c,[[12,-25],[23,-35],[23,-13]],'#bbb1c8')}else{path(c,[[-21,15],[-23,1],[-16,-13],[-8,-19],[7,-21],[20,-12],[24,4],[17,17],[4,14],[-6,20]],hit?'#fff2c9':'#9cae71');path(c,[[-10,-17],[-15,-30],[0,-22]],'#bbc78e');path(c,[[11,-18],[20,-27],[19,-10]],'#bbc78e')}oval(c,-8,-2,4,5,'#e8e6c4',null);oval(c,9,-2,4,5,'#e8e6c4',null);oval(c,-7,-1,2,3,'#333f29',null);oval(c,8,-1,2,3,'#333f29',null);c.strokeStyle='#343e2e';c.lineWidth=2;c.beginPath();c.moveTo(-5,9);c.lineTo(5,9);c.stroke();c.restore()}
function cactus(c,x,y,s=1){c.save();c.translate(x,y);c.scale(s,s);c.strokeStyle='#28372b';c.lineCap='round';c.lineWidth=14;c.beginPath();c.moveTo(0,11);c.lineTo(0,-25);c.moveTo(0,-4);c.lineTo(-14,-4);c.lineTo(-14,-16);c.moveTo(0,-13);c.lineTo(12,-13);c.lineTo(12,-27);c.stroke();c.strokeStyle='#657b4e';c.lineWidth=9;c.stroke();c.strokeStyle='#93a56e';c.lineWidth=1;c.beginPath();c.moveTo(-2,8);c.lineTo(-2,-26);c.stroke();c.restore()}
const decor=Array.from({length:120},(_,i)=>({x:((i*197.31+23)%1200),y:((i*91.67+37)%800),r:2+(i%4),type:i%11}));
function floor(c,hero=false){c.fillStyle=hero?'#47533a':'#596346';c.fillRect(0,0,1200,800);for(let d of decor){if(d.type===0){cactus(c,d.x,d.y,.6)}else if(d.type===1){oval(c,d.x,d.y,d.r*2,d.r,'#697255','#414f38',1)}else{c.strokeStyle='#46543a';c.lineWidth=1.5;c.beginPath();c.moveTo(d.x-3,d.y+2);c.lineTo(d.x,d.y-5);c.lineTo(d.x+2,d.y+1);c.lineTo(d.x+7,d.y-3);c.stroke()}}c.strokeStyle='#d1ce9d15';c.lineWidth=2;c.strokeRect(22,22,1156,756)}
function drawPoster(t){let r=fit(poster,pc),w=r.width,h=r.height;pc.clearRect(0,0,w,h);let s=Math.min(w/720,h/580);pc.save();pc.translate(w*.53,h*.52);pc.scale(s,s);let glow=pc.createRadialGradient(0,0,30,0,0,330);glow.addColorStop(0,'#53613b70');glow.addColorStop(.65,'#394b3045');glow.addColorStop(1,'#171d1b00');pc.fillStyle=glow;pc.fillRect(-420,-330,840,660);pc.save();pc.rotate(-.12);pc.strokeStyle='#62734a35';pc.lineWidth=1;for(let rad of [115,210,295]){pc.beginPath();pc.ellipse(0,34,rad,rad*.62,0,0,Math.PI*2);pc.stroke()}pc.restore();for(let i=0;i<40;i++){let x=Math.sin(i*47)*300,y=Math.cos(i*23)*190;oval(pc,x,y+50,1+(i%2),1,'#9baf6a35',null)}pc.save();pc.rotate(-.15);path(pc,[[-160,103],[-82,65],[100,78],[201,112],[100,156],[-89,158]],'#3b4930',null);pc.restore();cactus(pc,-205,57,1.5);cactus(pc,210,-32,.9);monster(pc,194,150,1.2,0,false,t*.3);monster(pc,-156,-106,1.1,0,false,t*.25);monster(pc,201,-143,.85,1,false,t*.2);monster(pc,-218,169,.7,0,false,t*.3);potato(pc,0,12,3.05,-.17,t*.12,true);for(let [x,y]of [[96,-78],[139,61],[-81,132]]){pc.save();pc.translate(x,y);pc.rotate(Math.PI/4);pc.fillStyle='#c5d984';pc.shadowColor='#b3d66c';pc.shadowBlur=14;pc.fillRect(-5,-5,10,10);pc.restore()}pc.strokeStyle='#f3bd66';pc.lineWidth=2;pc.beginPath();pc.moveTo(232,-26);pc.lineTo(245,-33);pc.moveTo(249,-14);pc.lineTo(258,-15);pc.stroke();pc.restore()}
function drawGame(t){let r=fit(canvas,ctx),s=Math.min(r.width/1200,r.height/800);viewW=r.width;viewH=r.height;ctx.fillStyle='#3c4932';ctx.fillRect(0,0,r.width,r.height);ctx.save();ctx.translate(r.width/2,r.height/2);let v=camera(r.width,r.height,g.x,g.y);ctx.scale(v.scale,v.scale);ctx.translate(-v.x,-v.y);if(shake>0){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);shake*=.85;if(shake<.3)shake=0}floor(ctx);for(let gem of g.gems){ctx.save();ctx.translate(gem.x,gem.y);ctx.rotate(Math.PI/4);ctx.fillStyle='#bbdc80';ctx.strokeStyle='#6d9e59';ctx.lineWidth=1.5;ctx.fillRect(-4,-4,8,8);ctx.strokeRect(-4,-4,8,8);ctx.restore()}let sprites=g.enemies.map(e=>({y:e.y,draw:()=>monster(ctx,e.x,e.y,e.r/19,e.type,e.hit>0,t)}));sprites.push({y:g.y,draw:()=>{if(g.inv>0&&Math.floor(t*18)%2===0)ctx.globalAlpha=.45;potato(ctx,g.x,g.y,.69,look,t);ctx.globalAlpha=1}});sprites.sort((a,b)=>a.y-b.y).forEach(s=>s.draw());for(let b of g.bullets){ctx.strokeStyle='#f5b954';ctx.lineWidth=5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(b.x-b.vx*.018,b.y-b.vy*.018);ctx.lineTo(b.x,b.y);ctx.stroke();oval(ctx,b.x,b.y,3,3,'#fff5bf',null)}for(let p of g.particles){ctx.globalAlpha=Math.min(1,p.life*3);oval(ctx,p.x,p.y,2.5,2.5,p.color,null)}ctx.globalAlpha=1;ctx.font='bold 16px system-ui';ctx.textAlign='center';for(let n of g.texts){ctx.globalAlpha=Math.min(1,n.life*3);ctx.fillStyle='#fff0b8';ctx.strokeStyle='#35432c';ctx.lineWidth=3;ctx.strokeText(n.value,n.x,n.y);ctx.fillText(n.value,n.x,n.y)}ctx.globalAlpha=1;ctx.restore()}
function beep(freq,duration=.05,type='sine',volume=.025){if(!sound)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),v=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);v.gain.setValueAtTime(volume,audio.currentTime);v.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(v);v.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}}
function start(){g.start();keys={};releaseJoy();$('home').classList.add('hidden');$('play').classList.remove('hidden');document.body.classList.add('playing');uiState='';last=performance.now();updateUI();canvas.focus({preventScroll:true});beep(330,.1)}
function home(){g.state='menu';keys={};releaseJoy();$('home').classList.remove('hidden');$('play').classList.add('hidden');document.body.classList.remove('playing');uiState='';updateUI()}
function pause(){if(g.state==='playing'){g.state='paused';keys={};releaseJoy()}else if(g.state==='paused')g.state='playing';updateUI()}
function choose(id){g.upgrade(id);keys={};updateUI();beep(660,.15)}
function updateUI(){let remain=Math.ceil(180-g.time);$('timer').textContent=`${String(Math.floor(remain/60)).padStart(2,'0')}:${String(remain%60).padStart(2,'0')}`;$('hpText').textContent=`${g.hp} / ${g.maxHp}`;$('hpBar').style.width=`${g.hp/g.maxHp*100}%`;$('kills').textContent=g.kills;$('level').textContent=`LV. ${g.level}`;$('xpText').textContent=`${g.xp} / ${g.needed}`;$('xpBar').style.width=`${Math.min(100,g.xp/g.needed*100)}%`;$('wave').textContent=`第 ${Math.floor(g.time/30)+1} 波 · ${['初入荒野','不速之客','四面楚歌','全力突围','生存本能','最后的黎明'][Math.min(5,Math.floor(g.time/30))]}`;$('buildStats').textContent=`伤害 ${g.damage} · 攻速 ${(1/g.rate).toFixed(1)}/s · 移速 ${g.speed}`;$('pause').textContent=g.state==='paused'?'▷':'Ⅱ';$('pause').setAttribute('aria-label',g.state==='paused'?'继续游戏':'暂停游戏');if(uiState===g.state)return;uiState=g.state;let overlay=$('overlay'),m=$('modal');overlay.classList.toggle('hidden',!['paused','upgrade','dead','won'].includes(g.state));if(g.state==='upgrade'){let opts=[...upgrades].sort(()=>Math.random()-.5).slice(0,3);m.innerHTML=`<div class="eyebrow">✦ LEVEL ${g.level}</div><h2>又强了一点。</h2><p>选一项强化，然后继续你的突围。</p><div class="upgrade-grid">${opts.map((u,i)=>`<button class="upgrade" data-upgrade="${u.id}"><span class="upgrade-icon">${u.icon}</span><strong>${u.name}</strong><small>${u.desc}<br>${u.detail}</small><em>${i+1}</em></button>`).join('')}</div>`;m.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>choose(b.dataset.upgrade));beep(760,.18)}else if(g.state==='paused'){m.innerHTML='<div class="eyebrow">TAKE A BREATHER</div><h2>歇口气，土豆。</h2><p>荒野会等你。准备好后，继续突围。</p><button class="primary" id="resume">继续游戏 <span>▷</span></button><button class="secondary" id="back">返回首页</button>';$('resume').onclick=pause;$('back').onclick=home}else if(['dead','won'].includes(g.state)){let win=g.state==='won';m.innerHTML=`<div class="eyebrow">${win?'✦ SURVIVOR':'UNTIL NEXT TIME'}</div><h2>${win?'这片荒野，你说了算。':'倒下了，但没认输。'}</h2><p>${win?'三分钟，扛住了。你是今天最硬核的土豆。':'每颗厉害的土豆，都曾在这里摔过跤。'}</p><div class="result-stats"><div><b>${Math.floor(g.time)}s</b><span>生存时间</span></div><div><b>${g.kills}</b><span>击败敌人</span></div><div><b>${g.level}</b><span>最终等级</span></div></div><button class="primary" id="restart">再来一局 <span>↻</span></button><button class="secondary" id="back">返回首页</button>`;$('restart').onclick=start;$('back').onclick=home}if(!overlay.classList.contains('hidden'))m.querySelector('button')?.focus({preventScroll:true})}
function releaseJoy(){joy={x:0,y:0};activePointer=null;$('stick').style.transform='translate(0,0)'}
function moveJoy(e){let r=$('joystick').getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,n=Math.hypot(dx,dy),scale=n>35?35/n:1;joy={x:dx*scale/35,y:dy*scale/35};$('stick').style.transform=`translate(${dx*scale}px,${dy*scale}px)`}
$('joystick').addEventListener('pointerdown',e=>{if(g.state!=='playing'||activePointer!==null)return;e.preventDefault();activePointer=e.pointerId;$('joystick').setPointerCapture(e.pointerId);moveJoy(e)});$('joystick').addEventListener('pointermove',e=>{if(e.pointerId===activePointer)moveJoy(e)});for(let name of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(name,e=>{if(e.pointerId===activePointer)releaseJoy()});
$('start').onclick=start;$('pause').onclick=pause;$('sound').onclick=()=>{sound=!sound;$('sound').querySelector('span').style.display=sound?'none':'block';$('sound').setAttribute('aria-label',sound?'关闭音效':'开启音效');if(sound)beep(440,.1)};
window.addEventListener('keydown',e=>{let key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(key))e.preventDefault();if(e.repeat)return;if(key==='enter'&&g.state==='menu'){e.preventDefault();start();return}if(key==='escape'){pause();return}if(g.state==='upgrade'&&['1','2','3'].includes(key)){$('modal').querySelectorAll('.upgrade')[Number(key)-1]?.click();return}keys[key]=true});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});window.addEventListener('blur',()=>{keys={};releaseJoy();if(g.state==='playing'){g.state='paused';updateUI()}});document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.hidden&&g.state==='playing'){g.state='paused';keys={};releaseJoy();updateUI()}});
function frame(now){let dt=Math.min(.05,(now-last)/1000||0);last=now;if(g.state==='menu')drawPoster(now/1000);else{let input={x:(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,y:(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y};g.tick(dt,input);if(g.enemies.length){let e=g.enemies.reduce((a,b)=>Math.hypot(a.x-g.x,a.y-g.y)<Math.hypot(b.x-g.x,b.y-g.y)?a:b);look=Math.atan2(e.y-g.y,e.x-g.x)}for(let event of g.events){if(event==='shot')beep(160,.035,'triangle',.012);if(event==='pickup')beep(850,.03,'sine',.008);if(event==='hurt'){shake=11;beep(75,.14,'sawtooth',.03)}}g.events=[];drawGame(now/1000);updateUI()}requestAnimationFrame(frame)}requestAnimationFrame(frame);
